INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c7070000-0000-4000-8000-000000000001', 'c7060000-0000-4000-8000-000000000001', 1, 'Which statement paraphrases the study''s finding correctly?', '[{"optionKey": "A", "content": "Short naps improved accuracy, but long naps did not.", "sortOrder": 1}, {"optionKey": "B", "content": "Any nap made workers more accurate.", "sortOrder": 2}, {"optionKey": "C", "content": "Workers who stayed awake made fewer errors.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'The benefit applied to twenty-minute naps and disappeared after half an hour.', 'MEDIUM', 'PUBLISHED');
