INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c7070000-0000-4000-8000-000000000002', 'c7060000-0000-4000-8000-000000000002', 1, '''Recent research has complicated that view'' means that research has', '[{"optionKey": "A", "content": "shown the view is too simple", "sortOrder": 1}, {"optionKey": "B", "content": "proved the view completely", "sortOrder": 2}, {"optionKey": "C", "content": "made napping illegal", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'Complicated means the old view no longer tells the whole story.', 'HARD', 'PUBLISHED');
