INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c7040000-0000-4000-8000-000000000004', 'c7030000-0000-4000-8000-000000000002', 1, 'TEXT', 'Tác giả học thuật hiếm khi khẳng định tuyệt đối. Các từ "appear to", "tends to", "may", "some", "a significant share" giới hạn mức độ của nhận định. Một đáp án nói "all", "always", "proves" thường sai vì phóng đại. Với dạng Yes/No/Not Given, câu hỏi hỏi quan điểm của tác giả, không phải sự thật: tìm "in my view", "it would be wrong", "the more reasonable lesson". No nghĩa là tác giả nói ngược lại, Not Given nghĩa là tác giả không bày tỏ quan điểm về điều đó.');
