INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c7040000-0000-4000-8000-000000000007', 'c7030000-0000-4000-8000-000000000003', 1, 'TEXT', 'Dạng bản đồ yêu cầu bạn theo người nói đi qua một tòa nhà hay khu vực. Trước khi nghe, xác định điểm xuất phát (As you come in...) và hướng: on the left/right, straight ahead, through the double doors, upstairs, behind, down the corridor. Theo dõi từng bước một, vì người nói đi theo thứ tự. Cẩn thận với thông tin sửa lại: "workshops are held in the main hall, not in the studio".');
