INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c7040000-0000-4000-8000-000000000010', 'c7030000-0000-4000-8000-000000000004', 1, 'TEXT', 'Trong Part 3, hai sinh viên và một giảng viên bàn kế hoạch. Câu hỏi thường hỏi ai đề xuất điều gì, ai đồng ý và vì sao người khác phản đối. Chú ý cách đồng ý ("That makes sense", "True") và cách phản đối nhẹ ("I would...", "Actually, I did a similar one"). Đáp án thường là ý kiến được chốt sau khi trao đổi, không phải đề xuất đầu tiên.');
