INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c7040000-0000-4000-8000-000000000013', 'c7030000-0000-4000-8000-000000000005', 1, 'TEXT', 'Band 7 cần nhiều cấu trúc phức được dùng chính xác: mệnh đề quan hệ rút gọn ("Students living far from campus..."), câu điều kiện loại 2 và 3, đảo ngữ nhẹ ("Not only does it save money, but it also..."), cụm phân từ ("Having finished the survey, the researchers..."). Mục tiêu không phải câu dài mà là câu rõ ý và không sai ngữ pháp. Một câu phức sai còn mất điểm hơn hai câu đơn đúng.');
