INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c7040000-0000-4000-8000-000000000015', 'c7030000-0000-4000-8000-000000000006', 1, 'TEXT', 'Một ý được phát triển đầy đủ gồm: luận điểm, giải thích vì sao, ví dụ cụ thể và hệ quả hoặc liên hệ lại câu hỏi. Lỗi phổ biến ở band 6 là liệt kê nhiều ý mà ý nào cũng chỉ một câu. Ở band 7, mỗi đoạn thân bài nên tập trung một ý chính và đào sâu nó. Hỏi "So what?" sau mỗi câu để biết mình đã giải thích đủ chưa.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c7040000-0000-4000-8000-000000000015', (SELECT id FROM knowledge_points WHERE code = 'W70_IDEA_DEVELOPMENT'));
