INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c7040000-0000-4000-8000-000000000017', 'c7030000-0000-4000-8000-000000000007', 1, 'TEXT', 'Lexical Resource band 7 đòi hỏi từ chính xác, không chỉ từ "khó". Phân biệt từ gần nghĩa: "affect" (động từ) và "effect" (danh từ); "economic" (thuộc kinh tế) và "economical" (tiết kiệm); "problem" và "issue". Chọn từ đúng sắc thái: "a dramatic rise" mạnh hơn "a noticeable rise". Tránh từ chung chung như "good", "bad", "things" khi có từ cụ thể hơn.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c7040000-0000-4000-8000-000000000017', (SELECT id FROM knowledge_points WHERE code = 'W70_LEXICAL_PRECISION'));
